  async function aiJpeg(blob, max) { const bm = await createImageBitmap(blob), k = Math.min(1, max / Math.max(bm.width, bm.height)), c = document.createElement('canvas'); c.width = Math.round(bm.width * k); c.height = Math.round(bm.height * k); c.getContext('2d').drawImage(bm, 0, 0, c.width, c.height); return (await b64(await new Promise(r => c.toBlob(r, 'image/jpeg', 0.82)))); }
